// Real order service using Supabase for read-only dashboard
import { supabase } from '../config/supabase';

class OrderService {
  constructor() {
    this.orders = [];
    this.lastFetchTime = null;
  }

  // Fetch ready orders from Supabase
  async fetchReadyOrders() {
    try {
      const { data, error } = await supabase
        .from('orders') // Assuming your table is named 'orders'
        .select('*')
        .eq('status', 'ready')
        .order('ready_at', { ascending: false }); // Newest first

      if (error) {
        console.error('Error fetching orders:', error);
        return [];
      }

      this.orders = data || [];
      this.lastFetchTime = Date.now();
      return this.orders;
    } catch (error) {
      console.error('Error in fetchReadyOrders:', error);
      return [];
    }
  }

  // Get ready orders (synchronous method for compatibility)
  getReadyOrders() {
    return this.orders
      .filter(order => order.status === 'ready')
      .sort((a, b) => b.ready_at - a.ready_at);
  }

  // Update orders from Supabase (replaces simulation)
  async updateOrders() {
    try {
      const previousOrderIds = this.orders.map(order => order.id);
      await this.fetchReadyOrders();
      const currentOrderIds = this.orders.map(order => order.id);

      return {
        newOrders: currentOrderIds.filter(id => !previousOrderIds.includes(id)),
        removedOrders: previousOrderIds.filter(id => !currentOrderIds.includes(id))
      };
    } catch (error) {
      console.error('Error updating orders:', error);
      return { newOrders: [], removedOrders: [] };
    }
  }

  addNewReadyOrder() {
    const customers = [
      'Alex Thompson', 'Maria Garcia', 'James Lee', 'Sophie Chen',
      'Robert Taylor', 'Anna Rodriguez', 'Kevin Park', 'Emma Wilson',
      'Daniel Kim', 'Olivia Brown', 'Lucas Martinez', 'Zoe Davis'
    ];

    const menuItems = [
      ['Grilled Salmon', 'Quinoa Salad', 'Green Tea'],
      ['Beef Stir Fry', 'White Rice', 'Miso Soup'],
      ['Veggie Wrap', 'Sweet Potato Chips', 'Fresh Juice'],
      ['Chicken Curry', 'Basmati Rice', 'Naan Bread'],
      ['Caesar Salad', 'Grilled Chicken', 'Sparkling Water'],
      ['Fish & Chips', 'Mushy Peas', 'Ale'],
      ['Margherita Pizza', 'Caesar Salad', 'Red Wine'],
      ['Burger Deluxe', 'Onion Rings', 'Craft Beer'],
      ['Pasta Alfredo', 'Garlic Bread', 'White Wine'],
      ['Taco Platter', 'Mexican Rice', 'Margarita']
    ];

    const randomCustomer = customers[Math.floor(Math.random() * customers.length)];
    const randomItems = menuItems[Math.floor(Math.random() * menuItems.length)];
    const randomCost = (Math.random() * 20 + 10).toFixed(2);
    const currentTime = new Date();
    const readyTime = currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    const now = Date.now();
    const newOrder = {
      id: ++this.orderIdCounter,
      tokenNumber: `T${String(this.orderIdCounter).padStart(3, '0')}`,
      customerName: randomCustomer,
      items: randomItems,
      cost: parseFloat(randomCost),
      readyTime: readyTime,
      status: 'ready',
      ready_at: now,
      timestamp: now
    };

    this.orders.push(newOrder);
  }

  removeRandomOrder() {
    const readyOrders = this.orders.filter(order => order.status === 'ready');
    if (readyOrders.length > 0) {
      const randomIndex = Math.floor(Math.random() * readyOrders.length);
      const orderToUpdate = readyOrders[randomIndex];
      const index = this.orders.findIndex(order => order.id === orderToUpdate.id);
      if (index !== -1) {
        // Simulate status change to 'collected' or 'completed'
        const statuses = ['collected', 'completed'];
        const newStatus = statuses[Math.floor(Math.random() * statuses.length)];
        this.orders[index].status = newStatus;
        this.orders[index].timestamp = Date.now();
      }
    }
  }

  // Get orders that were added since last check
  getNewOrders(lastTimestamp) {
    return this.orders.filter(order => 
      order.status === 'ready' && order.timestamp > lastTimestamp
    );
  }

  // Get orders that were removed since last check
  getRemovedOrders(currentOrderIds, previousOrderIds) {
    return previousOrderIds.filter(id => !currentOrderIds.includes(id));
  }
}

const orderServiceInstance = new OrderService();
export default orderServiceInstance;
